
#define GROUNDHOLDER_MACRO(nameN,dispName,classN,EdClassN,EdSubClassN) \
	class Item_##nameN## : Item_Base_F {\
			scope = 2;\
			scopeCurator = 2;\
			displayName = ##dispName##;\
			AUTHOR_MACRO \
			vehicleClass = ##classN##;\
			editorCategory = ##EdClassN##;\
			editorSubcategory = ##EdSubClassN##;\
			model = \A3\Weapons_f\dummyweapon.p3d;\
			class TransportItems {\
				class ##nameN## {\
				name = ##nameN##;\
				count = 1;\
			};\
		};\
	};
/*
WeaponAccessories
ItemsUniforms
ItemsHeadgear
ItemsVests

regex:
	(GROUNDHOLDER_MACRO\()"(.*?)(",)
	\1\2,
Generate with following script
["rhs_c_troops",0] execVM "rhsafrf\addons\rhs_main\scripts\generators\createGroundHolders.sqf"
*/
